using AcxiomCRM.Models;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Data;
public static class Seed{public static async Task Run(IServiceProvider sp,IConfiguration config){var db=sp.GetRequiredService<CrmDb>();await db.Database.MigrateAsync();var roles=sp.GetRequiredService<RoleManager<IdentityRole>>();var users=sp.GetRequiredService<UserManager<ApplicationUser>>();foreach(var role in new[]{"Admin","Manager","SalesExecutive"})if(!await roles.RoleExistsAsync(role)){var result=await roles.CreateAsync(new(role));if(!result.Succeeded)throw new InvalidOperationException("Role seed failed");}var password=config["Demo:Password"]??throw new InvalidOperationException("Set Demo:Password using user-secrets first.");async Task<ApplicationUser> Add(string name,string role,string? manager=null){var email=name+"@example.test";var u=await users.FindByEmailAsync(email);if(u!=null)return u;u=new(){UserName=email,Email=email,FullName=name,ManagerId=manager};var r=await users.CreateAsync(u,password);if(!r.Succeeded)throw new InvalidOperationException(string.Join(";",r.Errors.Select(x=>x.Description)));r=await users.AddToRoleAsync(u,role);if(!r.Succeeded)throw new InvalidOperationException("Role assignment failed");return u;}await Add("admin","Admin");var m1=await Add("manager1","Manager");var m2=await Add("manager2","Manager");var s1=await Add("sales1","SalesExecutive",m1.Id);var s2=await Add("sales2","SalesExecutive",m2.Id);if(await db.Customers.AnyAsync())return;for(int i=1;i<=25;i++){var owner=i%2==0?s1.Id:s2.Id;var c=new Customer{CustomerName=$"Demo customer {i:00}",CompanyName=$"Example company {i:00}",Email=$"customer{i}@example.test",NormalizedEmail=$"CUSTOMER{i}@EXAMPLE.TEST",Phone=$"900000{i:0000}",AssignedTo=owner,CreatedBy=owner};db.Add(c);await db.SaveChangesAsync();var l=new Lead{LeadName=$"Demo lead {i:00}",Email=$"lead{i}@example.test",Phone=$"800000{i:0000}",CompanyName=c.CompanyName,AssignedTo=owner,ExpectedValue=20000+i*2000,Status=new[]{"New","Contacted","Qualified","Lost"}[i%4]};db.Add(l);await db.SaveChangesAsync();if(i<=15){var stage=new[]{"Qualification","Proposal","Negotiation","Won","Lost"}[i%5];db.Add(new Opportunity{OpportunityName=$"Solution deal {i:00}",CustomerId=c.Id,LeadId=l.Id,AssignedTo=owner,Amount=25000+i*5000,Probability=20+i*4,Stage=stage,Status=stage is "Won" or "Lost"?stage:"Open",ExpectedCloseDate=DateTime.Today.AddDays(i),ActualCloseDate=stage is "Won" or "Lost"?DateTime.Today.AddDays(-i):null});}if(i<=12){db.Add(new FollowUp{Subject=$"Follow up {i}",CustomerId=c.Id,AssignedTo=owner,FollowUpDate=DateTime.Today.AddDays(i)});db.Add(new Activity{Subject=$"Customer call {i}",CustomerId=c.Id,AssignedTo=owner,Status="Completed"});}}await db.SaveChangesAsync();}}
